// Sub-path the app is served from (e.g. '/perfcompare'), set at build time
// via PERFCOMPARE_BASE_PATH. Empty when served from the site root.
export const basePath = process.env.PERFCOMPARE_BASE_PATH ?? '';

// Prefix an absolute app path for use in a plain <a href>. React Router
// links and forms already account for the basename and don't need this.
export const withBasePath = (path: string) => `${basePath}${path}`;
